import { type ReactNode, useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import {
  ArrowRight, BadgeCheck, Bell, BriefcaseBusiness, CalendarDays, CarFront,
  Check, ChevronRight, CircleAlert, CircleCheck, ClipboardList, Clock3,
  Droplets, Eye, EyeOff, Filter, Flower2, Heart, Home as HomeIcon,
  LayoutDashboard, Link2, LoaderCircle, LockKeyhole, LogIn, MapPin,
  Menu, MessageCircle, Navigation, Paintbrush, Phone, Plus, RefreshCw, Search, ShieldCheck,
  SlidersHorizontal, Sparkles, Star, TrendingUp, Truck, UserRound, Users, WalletCards,
  Wrench, X, Zap
} from 'lucide-react';
import {
  BookingStatus, BookingInputPaymentMethod, getGetAdminSummaryQueryKey, getGetBookingQueryKey,
  getGetHomeQueryKey, getGetProfessionalDashboardQueryKey, getGetServiceQueryKey,
  getHealthCheckQueryKey, getListBookingsQueryKey, getListCategoriesQueryKey,
  getListProfessionalsQueryKey, getListServicesQueryKey, useCreateBooking,
  useGetAdminSummary, useGetBooking, useGetHome, useGetProfessionalDashboard, useGetService,
  useHealthCheck, useListBookings, useListCategories, useListProfessionals, useListServices,
  type Booking, type Category, type Professional, type Service, type ServiceDetail
} from '@workspace/api-client-react';
import { Link, Route, Router as WouterRouter, Switch, useLocation, useParams } from 'wouter';
import { ErrorBoundary } from '@/components/error-boundary';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();

const categoryIcons: Record<string, typeof Wrench> = {
  cleaning: Sparkles, repair: Wrench, plumbing: Droplets, electrical: Zap,
  painting: Paintbrush, moving: Truck, gardening: Flower2, car: CarFront,
};

function CategoryIcon({ value, size = 21 }: { value: string; size?: number }) {
  const key = value.toLowerCase();
  const Icon = Object.entries(categoryIcons).find(([name]) => key.includes(name))?.[1] ?? Wrench;
  return <Icon size={size} strokeWidth={1.8} />;
}

function money(value: number) {
  return `₹${Math.round(value).toLocaleString('en-IN')}`;
}

function dateLabel(value: string, withTime = true) {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return parsed.toLocaleDateString('en-IN', {
    day: 'numeric', month: 'short', ...(withTime ? { hour: 'numeric', minute: '2-digit' } : {})
  });
}

function initials(name: string) {
  return name.split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase();
}

const statusMeta: Record<string, { label: string; className: string }> = {
  upcoming: { label: 'Upcoming', className: 'bg-[#eeeaff] text-[#5f4ab7]' },
  ongoing: { label: 'In progress', className: 'bg-[#e2f7f2] text-[#087c6a]' },
  completed: { label: 'Completed', className: 'bg-[#e9f0ff] text-[#2c5bb2]' },
  cancelled: { label: 'Cancelled', className: 'bg-[#fff0f0] text-[#bd5757]' },
};

function StatusPill({ status }: { status: string }) {
  const meta = statusMeta[status] ?? { label: status, className: 'bg-slate-100 text-slate-600' };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold tracking-wide ${meta.className}`}>{meta.label}</span>;
}

function StateBlock({ kind, title, detail, onRetry }: { kind: 'loading' | 'error' | 'empty'; title: string; detail: string; onRetry?: () => void }) {
  if (kind === 'loading') return (
    <div className="space-y-3" data-testid="state-loading">
      <div className="skeleton h-24 rounded-2xl" /><div className="skeleton h-24 rounded-2xl" /><div className="skeleton h-24 rounded-2xl" />
    </div>
  );
  return (
    <div className="surface flex flex-col items-center justify-center rounded-3xl px-6 py-14 text-center" data-testid={`state-${kind}`}>
      {kind === 'error' ? <CircleAlert className="mb-4 text-[#bd5757]" size={30} /> : <Search className="mb-4 text-primary" size={30} />}
      <h3 className="font-display text-lg font-bold">{title}</h3>
      <p className="mt-1 max-w-sm text-sm text-muted-foreground">{detail}</p>
      {onRetry && <button data-testid="button-retry" onClick={onRetry} className="mt-5 inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground transition-transform hover:-translate-y-0.5"><RefreshCw size={15} /> Try again</button>}
    </div>
  );
}

function Shell({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  const [open, setOpen] = useState(false);
  const nav = [
    { href: '/', label: 'Discover', icon: HomeIcon },
    { href: '/categories', label: 'Services', icon: SlidersHorizontal },
    { href: '/bookings', label: 'Bookings', icon: ClipboardList },
  ];
  const active = (href: string) => href === '/' ? location === '/' : location.startsWith(href);
  return (
    <div className="app-noise min-h-[100dvh] bg-background">
      <header className="sticky top-0 z-20 border-b border-border/80 bg-background/90 backdrop-blur-xl">
        <div className="mx-auto flex h-[72px] max-w-[1240px] items-center justify-between px-5 lg:px-8">
          <Link href="/" data-testid="link-logo" className="group flex items-center gap-2.5">
            <span className="relative flex h-9 w-9 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-[0_8px_18px_rgba(55,67,196,.22)]">
              <span className="font-display text-lg font-extrabold tracking-tight">S</span>
              <span className="absolute -right-1 -top-1 h-2.5 w-2.5 rounded-full bg-accent" />
            </span>
            <span className="font-display text-xl font-extrabold tracking-[-.04em]">sea<span className="text-accent">.</span></span>
          </Link>
          <nav className="hidden items-center gap-1 md:flex">
            {nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-nav-${label.toLowerCase()}`} className={`flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition-colors ${active(href) ? 'bg-secondary text-secondary-foreground' : 'text-muted-foreground hover:bg-muted hover:text-foreground'}`}><Icon size={16} />{label}</Link>)}
          </nav>
          <div className="hidden items-center gap-3 md:flex">
            <Link href="/professional" data-testid="link-professional" className="text-sm font-semibold text-muted-foreground transition-colors hover:text-foreground">For professionals</Link>
            <Link href="/login" data-testid="link-sign-in" className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-2.5 text-sm font-bold transition-colors hover:border-primary/30 hover:text-primary"><UserRound size={16} /> Sign in</Link>
          </div>
          <button data-testid="button-open-menu" aria-label="Open menu" onClick={() => setOpen(!open)} className="rounded-xl p-2 text-muted-foreground hover:bg-muted md:hidden">{open ? <X size={22} /> : <Menu size={22} />}</button>
        </div>
        {open && <div className="border-t border-border bg-card px-5 py-3 md:hidden">
          {nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} data-testid={`link-mobile-${label.toLowerCase()}`} className="flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold"><Icon size={17} />{label}</Link>)}
          <Link href="/professional" onClick={() => setOpen(false)} data-testid="link-mobile-professional" className="flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold"><BriefcaseBusiness size={17} />For professionals</Link>
        </div>}
      </header>
      <main>{children}</main>
      <nav className="fixed inset-x-0 bottom-0 z-20 flex justify-around border-t border-border bg-card/95 px-4 py-2 backdrop-blur-xl md:hidden">
        {nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-bottom-${label.toLowerCase()}`} className={`flex min-w-[78px] flex-col items-center gap-1 rounded-xl py-1 text-[10px] font-bold ${active(href) ? 'text-primary' : 'text-muted-foreground'}`}><Icon size={19} /><span>{label}</span></Link>)}
      </nav>
    </div>
  );
}

function PageIntro({ eyebrow, title, detail, action }: { eyebrow?: string; title: string; detail?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end">
    <div>{eyebrow && <p className="mb-2 text-xs font-bold uppercase tracking-[.18em] text-accent">{eyebrow}</p>}<h1 className="font-display text-3xl font-extrabold tracking-[-.04em] sm:text-4xl">{title}</h1>{detail && <p className="mt-2 max-w-xl text-sm leading-6 text-muted-foreground">{detail}</p>}</div>
    {action}
  </div>;
}

function ServiceCard({ service, compact = false }: { service: Service; compact?: boolean }) {
  return <Link href={`/services/${service.id}`} data-testid={`card-service-${service.id}`} className={`surface surface-hover group overflow-hidden rounded-2xl ${compact ? '' : 'min-w-[252px]'}`}>
    <div className={`relative overflow-hidden bg-secondary ${compact ? 'h-32' : 'h-40'}`}>
      <img src={service.imageUrl} alt={service.name} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" />
      <span className="absolute right-3 top-3 rounded-lg bg-card/90 px-2 py-1 text-xs font-bold text-foreground backdrop-blur-sm">{money(service.startingPrice)}+</span>
    </div>
    <div className="p-4"><div className="flex items-start justify-between gap-2"><h3 className="font-display text-[15px] font-bold leading-5">{service.name}</h3><Heart size={16} className="shrink-0 text-muted-foreground transition-colors group-hover:fill-accent group-hover:text-accent" /></div><p className="mt-1 line-clamp-1 text-xs text-muted-foreground">{service.description}</p><div className="mt-3 flex items-center gap-3 text-xs font-semibold"><span className="inline-flex items-center gap-1 text-[#ae7615]"><Star size={13} fill="currentColor" />{service.rating.toFixed(1)}</span><span className="text-muted-foreground">{service.duration}</span></div></div>
  </Link>;
}

function CategoryStrip({ categories }: { categories: Category[] }) {
  return <div className="scrollbar-hide flex gap-3 overflow-x-auto pb-1">{categories.map((category) => <Link href={`/categories?category=${category.id}`} key={category.id} data-testid={`card-category-${category.id}`} className="surface surface-hover flex min-w-[112px] flex-col items-center gap-3 rounded-2xl p-4 text-center"><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-secondary text-primary"><CategoryIcon value={category.icon} /></span><span className="text-xs font-bold">{category.name}</span><span className="-mt-2 text-[10px] text-muted-foreground">{category.serviceCount} services</span></Link>)}</div>;
}

function ProfessionalCard({ professional }: { professional: Professional }) {
  return <div className="surface surface-hover flex min-w-[270px] items-center gap-3 rounded-2xl p-4" data-testid={`card-professional-${professional.id}`}>
    {professional.photoUrl ? <img src={professional.photoUrl} alt={professional.name} className="h-14 w-14 rounded-2xl object-cover" /> : <span className="flex h-14 w-14 items-center justify-center rounded-2xl bg-secondary font-display font-bold text-primary">{initials(professional.name)}</span>}
    <div className="min-w-0 flex-1"><div className="flex items-center gap-1.5"><h3 className="truncate font-display text-sm font-bold">{professional.name}</h3>{professional.verified && <BadgeCheck size={14} className="shrink-0 text-primary" fill="currentColor" stroke="white" />}</div><p className="mt-1 truncate text-xs text-muted-foreground">{professional.skills.slice(0, 2).join(' · ')}</p><div className="mt-2 flex items-center justify-between text-xs"><span className="inline-flex items-center gap-1 font-bold text-[#ae7615]"><Star size={12} fill="currentColor" /> {professional.rating.toFixed(1)}</span><span className="text-muted-foreground">{professional.experience} exp.</span></div></div>
  </div>;
}

function Home() {
  const home = useGetHome({ query: { queryKey: getGetHomeQueryKey() } });
  const health = useHealthCheck({ query: { queryKey: getHealthCheckQueryKey() } });
  if (home.isLoading) return <Shell><HomeSkeleton /></Shell>;
  if (home.isError || !home.data) return <Shell><div className="mx-auto max-w-2xl px-5 py-24"><StateBlock kind="error" title="SEA is taking a breather" detail="We couldn't load your nearby services just now. Your place in line is safe." onRetry={() => home.refetch()} /></div></Shell>;
  const data = home.data;
  return <Shell><div className="mx-auto max-w-[1240px] px-5 pb-28 pt-8 lg:px-8 lg:pt-12">
    <div className="sea-rise mb-10 flex items-center justify-between"><div><p className="text-sm font-semibold text-muted-foreground">{data.greeting}</p><h1 className="mt-1 font-display text-3xl font-extrabold tracking-[-.05em] sm:text-4xl">What can we sort out<br className="sm:hidden" /> for you today?</h1></div><button data-testid="button-notifications" aria-label="Notifications" className="relative rounded-2xl border border-border bg-card p-3 text-muted-foreground transition-colors hover:text-primary"><Bell size={20} /><span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-accent" /></button></div>
    <div className="sea-rise sea-rise-2 relative mb-10 overflow-hidden rounded-[28px] bg-primary px-6 py-7 text-primary-foreground shadow-[0_18px_40px_rgba(55,67,196,.22)] sm:px-10 sm:py-9"><div className="relative z-10 max-w-xl"><div className="mb-5 inline-flex items-center gap-2 rounded-full bg-white/15 px-3 py-1.5 text-xs font-bold"><MapPin size={13} /> {data.location}</div><h2 className="font-display text-2xl font-extrabold leading-tight tracking-[-.04em] sm:text-3xl">Skilled help, right<br className="sm:hidden" /> when you need it.</h2><p className="mt-3 max-w-sm text-sm leading-6 text-white/75">Trusted professionals for the jobs that keep your home moving.</p><Link href="/categories" data-testid="link-browse-services" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-card px-4 py-3 text-sm font-bold text-primary transition-transform hover:-translate-y-0.5">Browse services <ArrowRight size={16} /></Link></div><div className="absolute -right-10 -top-20 h-72 w-72 rounded-full border-[34px] border-accent/45 sm:right-16 sm:top-[-90px]" /><div className="absolute -bottom-28 right-10 h-64 w-64 rounded-full border-[28px] border-white/10" /><span className="absolute bottom-6 right-8 hidden font-mono text-[10px] uppercase tracking-[.25em] text-white/50 sm:block">SEA / ALWAYS HERE</span></div>
    <div className="sea-rise sea-rise-3 surface mb-10 flex items-center gap-3 rounded-2xl p-2.5 focus-within:border-primary/50 sm:p-3"><Search className="ml-2 text-muted-foreground" size={20} /><input data-testid="input-home-search" placeholder="Search for a service, like AC repair" className="min-w-0 flex-1 bg-transparent px-1 text-sm outline-none placeholder:text-muted-foreground" /><Link href="/categories" data-testid="button-home-search" className="rounded-xl bg-secondary px-3 py-2 text-xs font-bold text-secondary-foreground sm:px-4">Search</Link></div>
    <section className="sea-rise sea-rise-4 mb-10"><div className="mb-4 flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Your home, covered</p><h2 className="mt-1 font-display text-xl font-extrabold">What do you need?</h2></div><Link href="/categories" data-testid="link-all-categories" className="inline-flex items-center gap-1 text-xs font-bold text-primary">See all <ChevronRight size={15} /></Link></div><CategoryStrip categories={data.categories} /></section>
    {data.recentlyBooked?.length > 0 && <section className="mb-10"><div className="mb-4 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Pick up where you left off</p><h2 className="mt-1 font-display text-xl font-extrabold">Your recent booking</h2></div><Link href="/bookings" data-testid="link-view-bookings" className="text-xs font-bold text-primary">View all</Link></div><BookingPreview booking={data.recentlyBooked[0]} /></section>}
    {data.offers?.length > 0 && <section className="mb-10"><div className="mb-4 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Good to know</p><h2 className="mt-1 font-display text-xl font-extrabold">Offers for your home</h2></div></div><div className="scrollbar-hide flex gap-3 overflow-x-auto pb-1">{data.offers.map((offer) => <div key={offer.id} className="relative min-w-[250px] overflow-hidden rounded-2xl p-5 text-white" style={{ background: offer.accent || '#6254c9' }} data-testid={`card-offer-${offer.id}`}><span className="font-mono text-[10px] font-bold uppercase tracking-[.18em] text-white/70">SEA SPECIAL</span><h3 className="mt-3 max-w-[180px] font-display text-xl font-extrabold leading-tight">{offer.title}</h3><p className="mt-1 text-xs text-white/75">{offer.subtitle}</p><span className="mt-5 inline-flex rounded-lg bg-white/15 px-2.5 py-1.5 font-mono text-[10px] font-bold tracking-wider">{offer.code}</span><Sparkles className="absolute -bottom-5 -right-3 h-24 w-24 text-white/15" /></div>)}</div></section>}
    <section className="mb-10"><div className="mb-4 flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Popular nearby</p><h2 className="mt-1 font-display text-xl font-extrabold">People are booking</h2></div><Link href="/categories" data-testid="link-popular-services" className="inline-flex items-center gap-1 text-xs font-bold text-primary">Explore <ChevronRight size={15} /></Link></div><div className="scrollbar-hide flex gap-4 overflow-x-auto pb-2">{data.popularServices.map((service) => <ServiceCard key={service.id} service={service} />)}</div></section>
    <section className="mb-4"><div className="mb-4"><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Checked by SEA</p><h2 className="mt-1 font-display text-xl font-extrabold">Verified professionals</h2></div><div className="scrollbar-hide flex gap-4 overflow-x-auto pb-2">{data.verifiedProfessionals.map((pro) => <ProfessionalCard key={pro.id} professional={pro} />)}</div></section>
    <p className="mt-8 flex items-center gap-2 text-[11px] text-muted-foreground"><span className={`h-1.5 w-1.5 rounded-full ${health.data?.status === 'ok' ? 'bg-[#16a085]' : 'bg-muted-foreground'}`} /> SEA services are live in your area</p>
  </div></Shell>;
}

function BookingPreview({ booking }: { booking: Booking }) {
  return <Link href={`/bookings/${booking.id}`} data-testid={`card-booking-preview-${booking.id}`} className="surface surface-hover flex flex-col gap-4 rounded-2xl p-4 sm:flex-row sm:items-center"><span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-secondary text-primary"><CalendarDays size={20} /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-display text-sm font-bold">{booking.service.name}</h3><StatusPill status={booking.status} /></div><p className="mt-1 text-xs text-muted-foreground">{dateLabel(booking.scheduledAt)} · {booking.address}</p></div><span className="flex items-center gap-1 text-xs font-bold text-primary">Track <ChevronRight size={15} /></span></Link>;
}

function HomeSkeleton() {
  return <div className="mx-auto max-w-[1240px] animate-pulse px-5 pb-24 pt-10 lg:px-8"><div className="skeleton h-10 w-72 rounded-lg" /><div className="skeleton mt-8 h-56 rounded-[28px]" /><div className="skeleton mt-8 h-16 rounded-2xl" /><div className="mt-8 grid grid-cols-2 gap-3 sm:grid-cols-5">{[1,2,3,4,5].map((item) => <div key={item} className="skeleton h-32 rounded-2xl" />)}</div></div>;
}

function Categories() {
  const params = new URLSearchParams(window.location.search);
  const initialCategory = params.get('category') ?? 'all';
  const [category, setCategory] = useState(initialCategory);
  const [search, setSearch] = useState('');
  const serviceParams = useMemo(() => ({ category: category === 'all' ? undefined : category, search: search || undefined }), [category, search]);
  const cats = useListCategories({ query: { queryKey: getListCategoriesQueryKey() } });
  const services = useListServices(serviceParams, { query: { queryKey: getListServicesQueryKey(serviceParams) } });
  const professionals = useListProfessionals(undefined, { query: { queryKey: getListProfessionalsQueryKey() } });
  const categoryList = cats.data ?? [];
  return <Shell><div className="mx-auto max-w-[1240px] px-5 pb-28 pt-9 lg:px-8 lg:pt-12"><PageIntro eyebrow="The SEA directory" title="Find your next fix." detail="From the everyday to the unexpected, every service is backed by professionals we have checked." action={<button data-testid="button-filter" className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-2.5 text-sm font-bold"><Filter size={16} /> Filters</button>} />
    <div className="surface mb-7 flex items-center gap-3 rounded-2xl px-4 py-3 focus-within:border-primary/50"><Search size={19} className="text-muted-foreground" /><input value={search} onChange={(event) => setSearch(event.target.value)} data-testid="input-service-search" placeholder="Search cleaning, repairs, moving..." className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground" /><span className="hidden rounded-lg bg-muted px-2 py-1 font-mono text-[10px] text-muted-foreground sm:block">⌘ K</span></div>
    {cats.isLoading ? <div className="skeleton mb-8 h-20 rounded-2xl" /> : cats.isError ? <StateBlock kind="error" title="Categories are unavailable" detail="We couldn't load the directory filters." onRetry={() => cats.refetch()} /> : <div className="scrollbar-hide mb-9 flex gap-2 overflow-x-auto pb-2"><button data-testid="button-category-all" onClick={() => setCategory('all')} className={`flex shrink-0 items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition-colors ${category === 'all' ? 'bg-primary text-primary-foreground' : 'bg-card text-muted-foreground shadow-sm hover:bg-secondary'}`}>All services</button>{categoryList.map((item) => <button key={item.id} data-testid={`button-category-${item.id}`} onClick={() => setCategory(item.id)} className={`flex shrink-0 items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition-colors ${category === item.id ? 'bg-primary text-primary-foreground' : 'bg-card text-muted-foreground shadow-sm hover:bg-secondary'}`}><CategoryIcon value={item.icon} size={16} />{item.name}</button>)}</div>}
    <div className="mb-10"><div className="mb-4 flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">{search ? 'Matching services' : 'Ready when you are'}</p><h2 className="mt-1 font-display text-2xl font-extrabold">{category === 'all' ? 'All services' : categoryList.find((item) => item.id === category)?.name ?? 'Services'}</h2></div>{services.data && <span className="text-xs font-semibold text-muted-foreground">{services.data.length} results</span>}</div>{services.isLoading ? <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><div className="skeleton h-72 rounded-2xl" /><div className="skeleton h-72 rounded-2xl" /><div className="skeleton h-72 rounded-2xl" /></div> : services.isError ? <StateBlock kind="error" title="Couldn't load services" detail="Try refreshing the directory or changing your search." onRetry={() => services.refetch()} /> : services.data?.length ? <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{services.data.map((service) => <ServiceCard key={service.id} service={service} compact />)}</div> : <StateBlock kind="empty" title="Nothing matched that search" detail="Try a broader phrase or explore another category." />}</div>
    {professionals.isSuccess && professionals.data.length > 0 && <section><div className="mb-4 flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Meet the makers</p><h2 className="mt-1 font-display text-2xl font-extrabold">Trusted in your area</h2></div><span className="text-xs font-semibold text-muted-foreground">{professionals.data.length} verified</span></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{professionals.data.slice(0, 6).map((pro) => <ProfessionalCard key={pro.id} professional={pro} />)}</div></section>}
  </div></Shell>;
}

function ServiceDetailPage() {
  const { serviceId = '' } = useParams<{ serviceId: string }>();
  const service = useGetService(serviceId, { query: { queryKey: getGetServiceQueryKey(serviceId), enabled: Boolean(serviceId) } });
  const professionals = useListProfessionals({ serviceId }, { query: { queryKey: getListProfessionalsQueryKey({ serviceId }), enabled: Boolean(serviceId) } });
  const createBooking = useCreateBooking();
  const [showBooking, setShowBooking] = useState(false);
  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  const [address, setAddress] = useState('');
  const [instructions, setInstructions] = useState('');
  const [payment, setPayment] = useState<BookingInputPaymentMethod>('upi');
  const [professionalId, setProfessionalId] = useState('');
  const [addOns, setAddOns] = useState<string[]>([]);
  const [created, setCreated] = useState<Booking | null>(null);
  if (service.isLoading) return <Shell><div className="mx-auto max-w-[1000px] px-5 py-12"><HomeSkeleton /></div></Shell>;
  if (service.isError || !service.data) return <Shell><div className="mx-auto max-w-2xl px-5 py-20"><StateBlock kind="error" title="Service details unavailable" detail="This service may have moved. Try the directory again." onRetry={() => service.refetch()} /></div></Shell>;
  const detail = service.data;
  const toggleAddOn = (id: string) => setAddOns((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
  const submitBooking = () => {
    if (!date || !time || !address) return;
    createBooking.mutate({ data: { serviceId, professionalId: professionalId || null, scheduledAt: `${date}T${time}`, address, instructions: instructions || null, addOnIds: addOns, paymentMethod: payment } }, { onSuccess: (booking) => setCreated(booking) });
  };
  if (created) return <Shell><div className="mx-auto max-w-2xl px-5 pb-28 pt-14"><div className="surface rounded-[28px] p-7 text-center sm:p-12"><span className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-[#e2f7f2] text-[#087c6a]"><CircleCheck size={32} /></span><p className="mt-6 text-xs font-bold uppercase tracking-[.18em] text-accent">You're on the list</p><h1 className="mt-2 font-display text-3xl font-extrabold tracking-[-.04em]">Booking request sent.</h1><p className="mx-auto mt-3 max-w-md text-sm leading-6 text-muted-foreground">We sent your request for {detail.name}. You can follow every update from your bookings.</p><div className="mt-8 rounded-2xl bg-muted p-4 text-left"><div className="flex justify-between text-sm"><span className="font-semibold">{detail.name}</span><span className="font-bold">{money(detail.startingPrice)}+</span></div><p className="mt-1 text-xs text-muted-foreground">{dateLabel(`${date}T${time}`)} · {address}</p></div><div className="mt-6 flex flex-col gap-3 sm:flex-row sm:justify-center"><Link href={`/bookings/${created.id}`} data-testid="link-track-new-booking" className="inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground">Track booking <ArrowRight size={16} /></Link><Link href="/categories" data-testid="link-book-another" className="inline-flex items-center justify-center rounded-xl border border-border px-5 py-3 text-sm font-bold">Browse more</Link></div></div></div></Shell>;
  return <Shell><div className="mx-auto max-w-[1120px] px-5 pb-28 pt-8 lg:px-8 lg:pt-12"><Link href="/categories" data-testid="link-back-services" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground hover:text-primary">← All services</Link><div className="grid gap-8 lg:grid-cols-[1fr_380px]"><div><div className="relative h-[250px] overflow-hidden rounded-[28px] bg-secondary sm:h-[350px]"><img src={detail.imageUrl} alt={detail.name} className="h-full w-full object-cover" /><span className="absolute bottom-4 left-4 rounded-xl bg-card/90 px-3 py-2 text-xs font-bold backdrop-blur-sm"><span className="text-[#ae7615]">★ {detail.rating.toFixed(1)}</span> <span className="text-muted-foreground">· {detail.bookings.toLocaleString('en-IN')} booked</span></span></div><div className="mt-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">SEA service</p><h1 className="mt-1 font-display text-3xl font-extrabold tracking-[-.04em] sm:text-4xl">{detail.name}</h1><p className="mt-3 max-w-xl leading-7 text-muted-foreground">{detail.description}</p></div><div className="text-right"><p className="text-xs text-muted-foreground">Starting at</p><p className="font-display text-2xl font-extrabold text-primary">{money(detail.startingPrice)}</p></div></div><div className="mt-6 flex flex-wrap gap-2"><span className="inline-flex items-center gap-2 rounded-xl bg-muted px-3 py-2 text-xs font-semibold"><Clock3 size={15} className="text-primary" /> {detail.duration}</span><span className="inline-flex items-center gap-2 rounded-xl bg-muted px-3 py-2 text-xs font-semibold"><ShieldCheck size={15} className="text-[#087c6a]" /> {detail.warranty}</span></div></div><div className="mt-10 grid gap-7 sm:grid-cols-2"><InfoList title="What's included" items={detail.included} good /><InfoList title="Not included" items={detail.excluded} /></div>{detail.reviews.length > 0 && <div className="mt-10"><h2 className="font-display text-xl font-extrabold">Notes from real homes</h2><div className="mt-4 grid gap-3 sm:grid-cols-2">{detail.reviews.slice(0, 4).map((review) => <div key={review.id} className="surface rounded-2xl p-4" data-testid={`review-${review.id}`}><div className="flex items-center justify-between"><span className="font-bold text-sm">{review.customerName}</span><span className="inline-flex items-center gap-1 text-xs font-bold text-[#ae7615]"><Star size={12} fill="currentColor" />{review.rating.toFixed(1)}</span></div><p className="mt-2 text-sm leading-6 text-muted-foreground">“{review.comment}”</p></div>)}</div></div>}</div>
      <BookingPanel detail={detail} professionals={professionals.data ?? []} showBooking={showBooking} setShowBooking={setShowBooking} date={date} setDate={setDate} time={time} setTime={setTime} address={address} setAddress={setAddress} instructions={instructions} setInstructions={setInstructions} payment={payment} setPayment={setPayment} professionalId={professionalId} setProfessionalId={setProfessionalId} addOns={addOns} toggleAddOn={toggleAddOn} onSubmit={submitBooking} pending={createBooking.isPending} error={createBooking.isError} />
    </div></div></Shell>;
}

function InfoList({ title, items, good = false }: { title: string; items: string[]; good?: boolean }) {
  return <div><h2 className="font-display text-base font-extrabold">{title}</h2><ul className="mt-3 space-y-3">{items.map((item) => <li key={item} className="flex gap-2 text-sm leading-5 text-muted-foreground"><Check size={16} className={`mt-0.5 shrink-0 ${good ? 'text-[#0a927e]' : 'text-muted-foreground'}`} />{item}</li>)}</ul></div>;
}

function BookingPanel({ detail, professionals, showBooking, setShowBooking, date, setDate, time, setTime, address, setAddress, instructions, setInstructions, payment, setPayment, professionalId, setProfessionalId, addOns, toggleAddOn, onSubmit, pending, error }: { detail: ServiceDetail; professionals: Professional[]; showBooking: boolean; setShowBooking: (value: boolean) => void; date: string; setDate: (value: string) => void; time: string; setTime: (value: string) => void; address: string; setAddress: (value: string) => void; instructions: string; setInstructions: (value: string) => void; payment: BookingInputPaymentMethod; setPayment: (value: BookingInputPaymentMethod) => void; professionalId: string; setProfessionalId: (value: string) => void; addOns: string[]; toggleAddOn: (id: string) => void; onSubmit: () => void; pending: boolean; error: boolean }) {
  if (!showBooking) return <aside className="lg:sticky lg:top-24 lg:self-start"><div className="surface rounded-[24px] p-5 sm:p-6"><div className="flex items-center justify-between"><span className="text-sm font-bold">Book this service</span><span className="rounded-lg bg-[#e2f7f2] px-2 py-1 text-[10px] font-bold text-[#087c6a]">Verified</span></div><p className="mt-3 text-sm leading-6 text-muted-foreground">Choose a time that works and we’ll match you with the right professional.</p><button data-testid="button-start-booking" onClick={() => setShowBooking(true)} className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3.5 text-sm font-bold text-primary-foreground transition-transform hover:-translate-y-0.5">Choose a time <ArrowRight size={16} /></button><div className="mt-5 flex items-center gap-2 text-xs text-muted-foreground"><ShieldCheck size={15} className="text-primary" /> Transparent pricing, trusted people</div></div></aside>;
  return <aside className="lg:sticky lg:top-24 lg:self-start"><div className="surface rounded-[24px] p-5 sm:p-6"><div className="flex items-center justify-between"><h2 className="font-display text-lg font-extrabold">Set up your visit</h2><button data-testid="button-close-booking" onClick={() => setShowBooking(false)} className="rounded-lg p-1.5 text-muted-foreground hover:bg-muted"><X size={17} /></button></div><div className="mt-5 grid grid-cols-2 gap-3"><label className="text-xs font-bold">Date<input data-testid="input-booking-date" type="date" value={date} onChange={(event) => setDate(event.target.value)} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:border-primary" /></label><label className="text-xs font-bold">Time<input data-testid="input-booking-time" type="time" value={time} onChange={(event) => setTime(event.target.value)} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:border-primary" /></label></div><label className="mt-4 block text-xs font-bold">Your address<input data-testid="input-booking-address" value={address} onChange={(event) => setAddress(event.target.value)} placeholder="Flat, street, area" className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:border-primary" /></label>{professionals.length > 0 && <label className="mt-4 block text-xs font-bold">Choose a professional<span className="mt-2 flex gap-2 overflow-x-auto pb-1">{professionals.slice(0, 3).map((pro) => <button type="button" key={pro.id} data-testid={`button-professional-${pro.id}`} onClick={() => setProfessionalId(pro.id)} className={`min-w-[106px] rounded-xl border p-2 text-left ${professionalId === pro.id ? 'border-primary bg-secondary' : 'border-border'}`}><span className="block truncate text-xs font-bold">{pro.name}</span><span className="mt-1 block text-[10px] text-muted-foreground">★ {pro.rating.toFixed(1)}</span></button>)}</span></label>} {detail.addOns.length > 0 && <div className="mt-4"><p className="text-xs font-bold">Add a little extra</p><div className="mt-2 space-y-2">{detail.addOns.map((item) => <label key={item.id} className="flex cursor-pointer items-center justify-between rounded-xl border border-border px-3 py-2.5 text-xs"><span className="flex items-center gap-2"><input data-testid={`input-addon-${item.id}`} type="checkbox" checked={addOns.includes(item.id)} onChange={() => toggleAddOn(item.id)} className="accent-primary" />{item.name}</span><span className="font-bold">{money(item.price)}</span></label>)}</div></div>}<label className="mt-4 block text-xs font-bold">Anything we should know?<textarea data-testid="input-booking-instructions" value={instructions} onChange={(event) => setInstructions(event.target.value)} placeholder="Optional note for your professional" rows={2} className="mt-2 w-full resize-none rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:border-primary" /></label><div className="mt-4"><p className="text-xs font-bold">Pay with</p><div className="mt-2 grid grid-cols-3 gap-2">{(['upi', 'card', 'cash'] as BookingInputPaymentMethod[]).map((method) => <button type="button" key={method} data-testid={`button-payment-${method}`} onClick={() => setPayment(method)} className={`rounded-xl border px-2 py-2 text-[11px] font-bold uppercase ${payment === method ? 'border-primary bg-secondary text-primary' : 'border-border text-muted-foreground'}`}>{method}</button>)}</div></div>{error && <p className="mt-4 text-xs font-semibold text-destructive" data-testid="status-booking-error">We couldn't send that request. Please try again.</p>}<button data-testid="button-submit-booking" onClick={onSubmit} disabled={pending || !date || !time || !address} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3.5 text-sm font-bold text-primary-foreground transition-transform hover:-translate-y-0.5 disabled:cursor-not-allowed disabled:opacity-50">{pending ? <><LoaderCircle className="animate-spin" size={16} /> Sending request</> : <>Request booking <ArrowRight size={16} /></>}</button></div></aside>;
}

function Bookings() {
  const bookings = useListBookings(undefined, { query: { queryKey: getListBookingsQueryKey() } });
  const [tab, setTab] = useState<'all' | keyof typeof BookingStatus>('all');
  const rows = bookings.data?.filter((booking) => tab === 'all' || booking.status === tab) ?? [];
  return <Shell><div className="mx-auto max-w-[1000px] px-5 pb-28 pt-9 lg:px-8 lg:pt-12"><PageIntro eyebrow="Your SEA timeline" title="Bookings" detail="Everything you’ve asked SEA to take care of, in one calm place." action={<Link href="/categories" data-testid="link-new-booking" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground"><Plus size={16} /> New booking</Link>} /><div className="scrollbar-hide mb-7 flex gap-2 overflow-x-auto pb-1">{['all', 'upcoming', 'ongoing', 'completed', 'cancelled'].map((item) => <button key={item} data-testid={`button-booking-tab-${item}`} onClick={() => setTab(item as typeof tab)} className={`shrink-0 rounded-xl px-4 py-2.5 text-xs font-bold capitalize ${tab === item ? 'bg-primary text-primary-foreground' : 'bg-card text-muted-foreground shadow-sm'}`}>{item === 'all' ? 'All bookings' : statusMeta[item].label}</button>)}</div>{bookings.isLoading ? <StateBlock kind="loading" title="" detail="" /> : bookings.isError ? <StateBlock kind="error" title="Your bookings are out of reach" detail="We couldn't load your timeline right now." onRetry={() => bookings.refetch()} /> : rows.length === 0 ? <StateBlock kind="empty" title={tab === 'all' ? 'Your first booking is waiting' : `No ${tab} bookings`} detail="When you book a trusted professional, the details will show up here." onRetry={tab === 'all' ? undefined : () => setTab('all')} /> : <div className="space-y-3">{rows.map((booking) => <BookingRow key={booking.id} booking={booking} />)}</div>}</div></Shell>;
}

function BookingRow({ booking }: { booking: Booking }) {
  return <Link href={`/bookings/${booking.id}`} data-testid={`row-booking-${booking.id}`} className="surface surface-hover flex flex-col gap-4 rounded-2xl p-4 sm:flex-row sm:items-center"><div className="flex min-w-0 flex-1 items-center gap-3"><span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-secondary text-primary"><Wrench size={19} /></span><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h3 className="truncate font-display text-sm font-bold">{booking.service.name}</h3><StatusPill status={booking.status} /></div><p className="mt-1 truncate text-xs text-muted-foreground">{dateLabel(booking.scheduledAt)} · {booking.address}</p></div></div><div className="flex items-center justify-between gap-6 sm:justify-end"><div className="text-left sm:text-right"><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Total</p><p className="mt-1 font-display font-extrabold">{money(booking.total)}</p></div><ChevronRight size={18} className="text-muted-foreground" /></div></Link>;
}

function BookingDetail() {
  const { bookingId = '' } = useParams<{ bookingId: string }>();
  const booking = useGetBooking(bookingId, { query: { queryKey: getGetBookingQueryKey(bookingId), enabled: Boolean(bookingId) } });
  if (booking.isLoading) return <Shell><div className="mx-auto max-w-2xl px-5 py-12"><HomeSkeleton /></div></Shell>;
  if (booking.isError || !booking.data) return <Shell><div className="mx-auto max-w-2xl px-5 py-20"><StateBlock kind="error" title="We lost that booking" detail="The tracking link may be out of date." onRetry={() => booking.refetch()} /></div></Shell>;
  const item = booking.data;
  const progress = Math.max(0, Math.min(100, item.progress));
  return <Shell><div className="mx-auto max-w-[860px] px-5 pb-28 pt-9 lg:px-8 lg:pt-12"><Link href="/bookings" data-testid="link-back-bookings" className="mb-7 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground hover:text-primary">← All bookings</Link><div className="mb-7 flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Booking #{item.id.slice(-6)}</p><h1 className="mt-2 font-display text-3xl font-extrabold tracking-[-.04em]">{item.service.name}</h1><p className="mt-2 text-sm text-muted-foreground">{dateLabel(item.scheduledAt)} · {item.address}</p></div><StatusPill status={item.status} /></div><div className="surface overflow-hidden rounded-[28px]"><div className="bg-primary px-6 py-7 text-primary-foreground sm:px-8"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-white/65">Live status</p><h2 className="mt-1 font-display text-2xl font-extrabold">{item.status === 'ongoing' ? 'Your professional is on the way' : item.status === 'completed' ? 'Job completed' : item.status === 'cancelled' ? 'Booking cancelled' : 'Your booking is confirmed'}</h2></div><Navigation className="text-white/60" size={30} /></div><div className="mt-7"><div className="flex justify-between text-xs font-bold text-white/70"><span>Request received</span><span>{item.status === 'ongoing' ? `${item.progress}% complete` : item.eta || 'SEA is coordinating'}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-white/20"><div className="h-full rounded-full bg-accent transition-all duration-500" style={{ width: `${progress}%` }} /></div></div></div><div className="grid gap-5 p-6 sm:grid-cols-2 sm:p-8"><div><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Your professional</p><div className="mt-3 flex items-center gap-3">{item.professional.photoUrl ? <img src={item.professional.photoUrl} alt={item.professional.name} className="h-12 w-12 rounded-2xl object-cover" /> : <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-secondary font-bold text-primary">{initials(item.professional.name)}</span>}<div><p className="font-display text-sm font-bold">{item.professional.name}</p><p className="mt-1 text-xs text-muted-foreground"><span className="text-[#ae7615]">★ {item.professional.rating.toFixed(1)}</span> · {item.professional.experience} experience</p></div></div></div><div><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Visit details</p><p className="mt-3 text-sm font-semibold">{dateLabel(item.scheduledAt)}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{item.address}</p></div></div><div className="flex flex-wrap gap-3 border-t border-border px-6 py-5 sm:px-8"><button data-testid="button-message-professional" className="inline-flex items-center gap-2 rounded-xl border border-border px-4 py-2.5 text-xs font-bold"><MessageCircle size={15} /> Message</button><button data-testid="button-call-professional" className="inline-flex items-center gap-2 rounded-xl border border-border px-4 py-2.5 text-xs font-bold"><Phone size={15} /> Call SEA support</button><span className="ml-auto self-center font-display text-lg font-extrabold">{money(item.total)}</span></div></div></div></Shell>;
}

function ProfessionalDashboard() {
  const dashboard = useGetProfessionalDashboard({ query: { queryKey: getGetProfessionalDashboardQueryKey() } });
  if (dashboard.isLoading) return <Shell><div className="mx-auto max-w-[1100px] px-5 py-12"><HomeSkeleton /></div></Shell>;
  if (dashboard.isError || !dashboard.data) return <Shell><div className="mx-auto max-w-2xl px-5 py-20"><StateBlock kind="error" title="Dashboard unavailable" detail="We couldn't load your professional workspace." onRetry={() => dashboard.refetch()} /></div></Shell>;
  const data = dashboard.data;
  return <Shell><div className="mx-auto max-w-[1100px] px-5 pb-28 pt-9 lg:px-8 lg:pt-12"><div className="mb-9 flex flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-3">{data.professional.photoUrl ? <img src={data.professional.photoUrl} alt={data.professional.name} className="h-14 w-14 rounded-2xl object-cover" /> : <span className="flex h-14 w-14 items-center justify-center rounded-2xl bg-secondary font-display text-xl font-bold text-primary">{initials(data.professional.name)}</span>}<div><p className="text-sm text-muted-foreground">Good morning</p><h1 className="font-display text-2xl font-extrabold tracking-[-.04em]">{data.professional.name}</h1></div></div><button data-testid="button-availability" className={`inline-flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold ${data.isOnline ? 'bg-[#e2f7f2] text-[#087c6a]' : 'bg-muted text-muted-foreground'}`}><span className={`h-2 w-2 rounded-full ${data.isOnline ? 'bg-[#0a927e]' : 'bg-muted-foreground'}`} />{data.isOnline ? 'You’re online' : 'Go online'}</button></div><div className="mb-8 rounded-[26px] bg-primary p-6 text-primary-foreground sm:p-8"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-white/65">Today’s pulse</p><p className="mt-2 font-display text-4xl font-extrabold">{money(data.todayEarnings)}</p><p className="mt-1 text-sm text-white/70">earned so far today</p></div><TrendingUp className="text-white/50" size={34} /></div><div className="mt-7 grid grid-cols-3 gap-2 border-t border-white/15 pt-5"><div><p className="font-display text-xl font-extrabold">{data.todayJobs}</p><p className="mt-1 text-[11px] text-white/65">Today’s jobs</p></div><div><p className="font-display text-xl font-extrabold">{data.pendingRequests}</p><p className="mt-1 text-[11px] text-white/65">New requests</p></div><div><p className="font-display text-xl font-extrabold">{data.upcomingJobs}</p><p className="mt-1 text-[11px] text-white/65">Upcoming</p></div></div></div><div className="grid gap-4 sm:grid-cols-3"><div className="surface rounded-2xl p-5"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Requests</p><ClipboardList size={18} className="text-accent" /></div><p className="mt-5 font-display text-2xl font-extrabold">{data.pendingRequests}</p><p className="mt-1 text-xs text-muted-foreground">Need your attention</p><button data-testid="button-view-requests" className="mt-4 text-xs font-bold text-primary">Review requests <ArrowRight className="ml-1 inline" size={13} /></button></div><div className="surface rounded-2xl p-5"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Profile trust</p><BadgeCheck size={18} className="text-primary" /></div><p className="mt-5 font-display text-2xl font-extrabold">{data.professional.rating.toFixed(1)} <span className="text-sm text-[#ae7615]">★</span></p><p className="mt-1 text-xs text-muted-foreground">{data.professional.totalJobs} jobs completed</p><button data-testid="button-view-profile" className="mt-4 text-xs font-bold text-primary">View profile <ArrowRight className="ml-1 inline" size={13} /></button></div><div className="surface rounded-2xl p-5"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Payouts</p><WalletCards size={18} className="text-accent" /></div><p className="mt-5 font-display text-2xl font-extrabold">Weekly</p><p className="mt-1 text-xs text-muted-foreground">Next payout is Friday</p><button data-testid="button-view-payouts" className="mt-4 text-xs font-bold text-primary">View earnings <ArrowRight className="ml-1 inline" size={13} /></button></div></div></div></Shell>;
}

function Admin() {
  const summary = useGetAdminSummary({ query: { queryKey: getGetAdminSummaryQueryKey() } });
  if (summary.isLoading) return <Shell><div className="mx-auto max-w-[1100px] px-5 py-12"><HomeSkeleton /></div></Shell>;
  if (summary.isError || !summary.data) return <Shell><div className="mx-auto max-w-2xl px-5 py-20"><StateBlock kind="error" title="Operations view unavailable" detail="We couldn't load the marketplace summary." onRetry={() => summary.refetch()} /></div></Shell>;
  const data = summary.data;
  const metrics = [{ label: 'Total users', value: data.totalUsers.toLocaleString('en-IN'), note: `${data.activeUsers.toLocaleString('en-IN')} active`, icon: Users }, { label: 'Professionals', value: data.totalProfessionals.toLocaleString('en-IN'), note: `${data.activeProfessionals.toLocaleString('en-IN')} active`, icon: BriefcaseBusiness }, { label: 'Bookings', value: data.totalBookings.toLocaleString('en-IN'), note: `${data.completedBookings.toLocaleString('en-IN')} completed`, icon: ClipboardList }, { label: 'GMV', value: money(data.gmv), note: `${money(data.averageOrderValue)} avg order`, icon: TrendingUp }];
  return <Shell><div className="mx-auto max-w-[1100px] px-5 pb-28 pt-9 lg:px-8 lg:pt-12"><PageIntro eyebrow="SEA operations" title="Marketplace pulse" detail="A clear read on the people, professionals, and bookings moving through SEA." action={<span className="inline-flex items-center gap-2 rounded-xl bg-[#e2f7f2] px-3 py-2 text-xs font-bold text-[#087c6a]"><span className="h-1.5 w-1.5 animate-pulse rounded-full bg-[#0a927e]" /> Live data</span>} /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{metrics.map(({ label, value, note, icon: Icon }) => <div key={label} className="surface rounded-2xl p-5" data-testid={`metric-${label.toLowerCase().replace(' ', '-')}`}><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">{label}</p><Icon size={18} className="text-accent" /></div><p className="mt-5 font-display text-2xl font-extrabold">{value}</p><p className="mt-1 text-xs text-muted-foreground">{note}</p></div>)}</div><div className="mt-6 grid gap-4 lg:grid-cols-[1.2fr_.8fr]"><div className="surface rounded-2xl p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Booking health</p><h2 className="mt-1 font-display text-xl font-extrabold">Fulfilment at a glance</h2></div><LayoutDashboard size={19} className="text-primary" /></div><div className="mt-7 space-y-5"><MetricBar label="Completed bookings" value={data.completedBookings} total={data.totalBookings} color="bg-primary" /><MetricBar label="Cancelled bookings" value={data.cancelledBookings} total={data.totalBookings} color="bg-accent" /><MetricBar label="Active professionals" value={data.activeProfessionals} total={data.totalProfessionals} color="bg-[#0a927e]" /></div></div><div className="surface rounded-2xl p-6"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Revenue stack</p><h2 className="mt-1 font-display text-xl font-extrabold">This marketplace</h2><div className="mt-6 space-y-4">{[['Gross merchandise value', data.gmv], ['SEA revenue', data.revenue], ['Commission earned', data.commission]].map(([label, value]) => <div key={label as string} className="flex items-center justify-between border-b border-border pb-3 text-sm"><span className="text-muted-foreground">{label}</span><span className="font-display font-extrabold">{money(value as number)}</span></div>)}</div><button data-testid="button-export-summary" className="mt-5 inline-flex items-center gap-2 text-xs font-bold text-primary"><Link2 size={14} /> Share summary</button></div></div></div></Shell>;
}

function MetricBar({ label, value, total, color }: { label: string; value: number; total: number; color: string }) {
  const percent = total ? Math.min(100, Math.round((value / total) * 100)) : 0;
  return <div><div className="mb-2 flex justify-between text-xs font-semibold"><span>{label}</span><span className="text-muted-foreground">{percent}%</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${color}`} style={{ width: `${percent}%` }} /></div></div>;
}

function Login() {
  const [showPassword, setShowPassword] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  return <div className="app-noise flex min-h-[100dvh] items-center justify-center bg-primary px-5 py-10"><div className="grid w-full max-w-[980px] overflow-hidden rounded-[30px] bg-card shadow-[0_24px_80px_rgba(24,31,104,.25)] md:grid-cols-[.9fr_1.1fr]"><div className="relative hidden overflow-hidden bg-primary p-10 text-primary-foreground md:block"><Link href="/" data-testid="link-login-logo" className="flex items-center gap-2 font-display text-xl font-extrabold">sea<span className="text-accent">.</span></Link><div className="relative z-10 mt-28"><p className="text-xs font-bold uppercase tracking-[.2em] text-white/60">Home feels better</p><h1 className="mt-3 font-display text-4xl font-extrabold leading-tight tracking-[-.05em]">Your trusted<br />help desk, at home.</h1><p className="mt-5 max-w-xs text-sm leading-6 text-white/70">Save your addresses, follow bookings, and get the people you trust back in a few taps.</p></div><div className="absolute -bottom-20 -right-20 h-80 w-80 rounded-full border-[34px] border-accent/40" /><div className="absolute right-10 top-1/3 h-24 w-24 rounded-full border border-white/20" /></div><div className="p-7 sm:p-12"><Link href="/" data-testid="link-login-mobile-logo" className="font-display text-xl font-extrabold md:hidden">sea<span className="text-accent">.</span></Link>{submitted ? <div className="flex min-h-[390px] flex-col justify-center"><span className="flex h-12 w-12 items-center justify-center rounded-full bg-[#e2f7f2] text-[#087c6a]"><CircleCheck size={25} /></span><h2 className="mt-6 font-display text-3xl font-extrabold tracking-[-.04em]">Check your inbox.</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">We’ve sent a secure sign-in link to your email. This demo keeps your data private and simple.</p><button data-testid="button-login-back" onClick={() => setSubmitted(false)} className="mt-7 text-left text-sm font-bold text-primary">Use another email</button></div> : <><div className="mt-14 md:mt-12"><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Welcome back</p><h2 className="mt-2 font-display text-3xl font-extrabold tracking-[-.04em]">Sign in to SEA</h2><p className="mt-3 text-sm text-muted-foreground">Your next useful thing is only a few taps away.</p></div><form onSubmit={(event) => { event.preventDefault(); setSubmitted(true); }} className="mt-8 space-y-4"><label className="block text-xs font-bold">Email address<input data-testid="input-login-email" required type="email" placeholder="you@example.com" className="mt-2 w-full rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus:border-primary" /></label><label className="block text-xs font-bold">Password<span className="relative mt-2 block"><input data-testid="input-login-password" required type={showPassword ? 'text' : 'password'} placeholder="Enter your password" className="w-full rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus:border-primary" /><button type="button" data-testid="button-toggle-password" aria-label="Toggle password visibility" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground">{showPassword ? <EyeOff size={17} /> : <Eye size={17} />}</button></span></label><div className="flex justify-end"><button type="button" data-testid="button-forgot-password" className="text-xs font-bold text-primary">Forgot password?</button></div><button type="submit" data-testid="button-submit-login" className="flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3.5 text-sm font-bold text-primary-foreground transition-transform hover:-translate-y-0.5"><LogIn size={16} /> Sign in</button></form><div className="my-6 flex items-center gap-3 text-[11px] text-muted-foreground"><span className="h-px flex-1 bg-border" />or<span className="h-px flex-1 bg-border" /></div><button data-testid="button-continue-guest" onClick={() => setSubmitted(true)} className="w-full rounded-xl border border-border px-4 py-3 text-sm font-bold transition-colors hover:bg-muted">Continue as guest</button><p className="mt-7 text-center text-[11px] leading-5 text-muted-foreground"><LockKeyhole size={12} className="mr-1 inline" /> Your information is encrypted and never shared.</p></>}</div></div></div>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch><Route path="/" component={Home} /><Route path="/categories" component={Categories} /><Route path="/services/:serviceId" component={ServiceDetailPage} /><Route path="/bookings" component={Bookings} /><Route path="/bookings/:bookingId" component={BookingDetail} /><Route path="/professional" component={ProfessionalDashboard} /><Route path="/admin" component={Admin} /><Route path="/login" component={Login} /><Route component={NotFound} /></Switch></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter></QueryClientProvider>;
}

export default App;